def verifier(assign):
    # Validate presence and types
    for k in ['odd_m','p','q','q0','q1','q2']:
        if k not in assign:
            # Missing slot
            return (False, None)
        if not isinstance(assign[k], int):
            # Type mismatch
            return (False, None)
    odd_m = assign['odd_m']
    p = assign['p']
    q = assign['q']
    q0 = assign['q0']
    q1 = assign['q1']
    q2 = assign['q2']
    # Domain constraints
    if odd_m not in [5,7,9]:
        return (False, None)
    if not (p > q >= 1):
        return (False, None)
    # Recompute Q polynomial to ensure the trig ratio equals odd_m exactly
    def poly_add(a, b):
        n = max(len(a), len(b))
        c = [0]*n
        for i in range(n):
            c[i] = (a[i] if i < len(a) else 0) + (b[i] if i < len(b) else 0)
        return c
    def poly_sub(a, b):
        n = max(len(a), len(b))
        c = [0]*n
        for i in range(n):
            ai = a[i] if i < len(a) else 0
            bi = b[i] if i < len(b) else 0
            c[i] = ai - bi
        return c
    def poly_mul(a, b):
        c = [0]*(len(a)+len(b)-1)
        for i, ai in enumerate(a):
            for j, bj in enumerate(b):
                c[i+j] += ai*bj
        return c
    def poly_scale(a, s):
        return [ai*s for ai in a]
    def poly_degree(a):
        d = len(a)-1
        while d>0 and abs(a[d])<1e-12:
            d -= 1
        return d
    def poly_trim(a):
        d = poly_degree(a)
        return a[:d+1]
    def poly_div(dividend, divisor):
        A = dividend[:]
        B = divisor[:]
        A = poly_trim(A)
        B = poly_trim(B)
        da = poly_degree(A)
        db = poly_degree(B)
        if db < 0:
            return (False, None)
        if da < db:
            return [0], A
        Q = [0]*(da-db+1)
        R = A[:]
        while poly_degree(R) >= db and any(abs(x)>1e-18 for x in R):
            dr = poly_degree(R)
            coeff = R[dr] / B[db]
            shift = dr - db
            term = [0]*(shift) + [coeff]
            Q = poly_add(Q, term)
            R = poly_sub(R, poly_mul(B, term))
            R = poly_trim(R)
        Q = poly_trim(Q)
        R = poly_trim(R)
        return Q, R
    def chebyshev_T_poly(n):
        T0 = [1]
        if n == 0:
            return T0
        T1 = [0,1]
        if n == 1:
            return T1
        prev = T0
        curr = T1
        for k in range(1, n):
            two_x_curr = [0] + [2*c for c in curr]
            nxt = poly_sub(two_x_curr, prev)
            prev, curr = curr, nxt
        return curr
    Tm = chebyshev_T_poly(odd_m)
    xm = [0]*odd_m + [1]
    D = poly_sub(poly_scale(xm, 2**(odd_m-1)), Tm)
    T3 = chebyshev_T_poly(3)
    two_x = [0,2]
    denom1 = poly_add(two_x, T3)
    Qpoly, Rem = poly_div(D, poly_scale(denom1, odd_m))
    Qpoly = poly_trim(Qpoly)
    # Validate q0,q1,q2 match Qpoly's even-degree coefficients
    def coeff_at(poly, k):
        return poly[k] if k < len(poly) else 0
    q0c = int(round(coeff_at(Qpoly, 0)))
    q1c = int(round(coeff_at(Qpoly, 2)))
    q2c = int(round(coeff_at(Qpoly, 4)))
    if (q0, q1, q2) != (q0c, q1c, q2c):
        # The provided coefficients do not match the identity needed to force constancy.
        return (False, None)
    # Now solve the constrained maximization for R_alg(p,q)
    import math
    # Define tau = (q/p)^{1/p}
    tau = (q/float(p))**(1.0/p)
    def H(s):
        # H(s) = q s^p + p tau^q s^{q^2/p} - p s^{-q}
        return q*(s**p) + p*((tau**q)*(s**(q*q/float(p)))) - p*(s**(-q))
    # Bracket and bisection; H(0+) -> -inf, H(\infty) -> +inf, so root exists
    lo = 10**(-6)
    hi = 10**(6)
    # Ensure signs
    hlo = H(lo)
    hhi = H(hi)
    # If for numerical reasons signs don't bracket well, expand
    tries = 0
    while not (hlo < 0 and hhi > 0) and tries < 20:
        lo *= 0.1
        hi *= 10.0
        hlo = H(lo)
        hhi = H(hi)
        tries += 1
    if not (hlo < 0 and hhi > 0):
        # Failed to bracket (shouldn't happen for valid p,q)
        return (False, None)
    # Bisection
    for _ in range(120):
        mid = 0.5*(lo+hi)
        hmid = H(mid)
        if hmid == 0:
            lo = hi = mid
            break
        if hmid > 0:
            hi = mid
        else:
            lo = mid
    s = 0.5*(lo+hi)
    # Compute t from t^p = (q/p) s^q
    t = tau * (s**(q/float(p)))
    # Compute R = (s^p + t^q) / (s^{p+q} + 1 + t^{p+q})
    numer = (s**p) + (t**q)
    denom = (s**(p+q)) + 1.0 + (t**(p+q))
    R_alg = numer/denom
    # Enforce non-triviality: value should be in (0,1) for all chosen pairs; check bounds to ensure difficulty
    if not (0.05 < R_alg < 0.95):
        return (False, None)
    # Overall maximum multiplies by the constant trig ratio = odd_m
    max_value = odd_m * R_alg
    # Format answer with at least 10 decimal places
    ans_str = f"### The final answer is: \\boxed{{{max_value:.10f}}}"
    return (True, ans_str)
